"""Authored cross section and route for NRS 484B.297(6) CPU preparation.

Coordinates are local engineering metres, not a surveyed CARLA map or a legal
finding. The operator must bind these shapes to a verified sidewalk/highway.
"""

from dataclasses import dataclass
from math import hypot


@dataclass(frozen=True)
class Rectangle:
    name: str
    x0: float
    x1: float
    y0: float
    y1: float

    def contains(self, x: float, y: float) -> bool:
        return self.x0 <= x <= self.x1 and self.y0 <= y <= self.y1


@dataclass(frozen=True)
class Scene:
    case_id: str
    direction: int
    sidewalk_end: float
    area_blocked: bool
    obstruction_kind: str
    sidewalk: Rectangle
    intervening_area: Rectangle
    designated_lane: Rectangle
    highway: Rectangle
    obstacles: tuple[Rectangle, ...]
    missing_sections: tuple[Rectangle, ...]
    route: tuple[tuple[float, float], ...]


def construct(case_id: str, *, direction: int = 1, area_blocked: bool = False,
              sidewalk_end: float = 34.0, obstruction_kind: str = "impassable_section") -> Scene:
    if direction not in (-1, 1):
        raise ValueError("direction must be +1 or -1")
    if sidewalk_end not in (34.0, 40.0):
        raise ValueError("unsupported authored sidewalk end")
    if obstruction_kind not in ("impassable_section", "missing_section"):
        raise ValueError("unsupported obstruction kind")
    sidewalk = Rectangle("sidewalk", 0, 60, 4, 6)
    area = Rectangle("intervening_area", 0, 60, 2, 4)
    lane = Rectangle("designated_bicycle_lane", 0, 60, 0, 2)
    highway = Rectangle("immediately_adjacent_highway", 0, 60, -3, 4)
    obstacles = []
    missing_sections = []
    if obstruction_kind == "missing_section":
        missing_sections.append(Rectangle("missing_sidewalk_surface", 20, sidewalk_end, 4, 6))
    else:
        obstacles.append(Rectangle("impassable_sidewalk_section", 20, sidewalk_end, 4, 6))
    if area_blocked:
        obstacles.append(Rectangle("intervening_barrier", 20, sidewalk_end, 2, 4))
    bypass_y = 1.0 if area_blocked else 3.0
    if direction == 1:
        route = ((10, 5), (17, 5), (18, bypass_y),
                 (sidewalk_end + 2, bypass_y), (sidewalk_end + 3, 5), (50, 5))
    else:
        route = ((50, 5), (sidewalk_end + 3, 5),
                 (sidewalk_end + 2, bypass_y), (18, bypass_y), (17, 5), (10, 5))
    return Scene(case_id, direction, sidewalk_end, area_blocked, obstruction_kind,
                 sidewalk, area, lane, highway, tuple(obstacles), tuple(missing_sections), route)


def sample_route(route: tuple[tuple[float, float], ...], step: float = 0.05):
    """Yield dense engineering samples, including endpoints, for obstruction checks."""
    for (ax, ay), (bx, by) in zip(route, route[1:]):
        n = max(1, int(hypot(bx - ax, by - ay) / step) + 1)
        for i in range(n + 1):
            t = i / n
            yield ax + t * (bx - ax), ay + t * (by - ay)


def audit_design(scene: Scene) -> dict:
    """Check authored shapes; never infer statutory due care or impassability."""
    if scene.intervening_area.y1 != scene.sidewalk.y0:
        raise ValueError("intervening area does not border sidewalk")
    if scene.designated_lane.y1 != scene.intervening_area.y0:
        raise ValueError("designated lane does not border intervening area")
    if scene.highway.y1 != scene.sidewalk.y0:
        raise ValueError("highway is not adjacent to sidewalk")
    sidewalk_blocks = scene.obstacles if scene.obstruction_kind == "impassable_section" else scene.missing_sections
    if not any(o.x0 == 20 and o.x1 == scene.sidewalk_end and
               o.y0 == scene.sidewalk.y0 and o.y1 == scene.sidewalk.y1 for o in sidewalk_blocks):
        raise ValueError("sidewalk obstruction is not constructed")
    if scene.area_blocked != any(o.name == "intervening_barrier" for o in scene.obstacles):
        raise ValueError("intervening barrier does not match case")
    if scene.direction * (scene.route[-1][0] - scene.route[0][0]) <= 0:
        raise ValueError("route travels against authored direction")
    samples = tuple(sample_route(scene.route))
    if any(o.contains(x, y) for x, y in samples for o in (*scene.obstacles, *scene.missing_sections)):
        raise ValueError("pedestrian route intersects constructed obstruction")
    in_lane = any(scene.designated_lane.y0 < y < scene.designated_lane.y1
                  for _, y in samples)
    if in_lane != scene.area_blocked:
        raise ValueError("designated-lane use is not isolated to blocked-area case")
    if not any(20 <= x <= scene.sidewalk_end for x, _ in samples):
        raise ValueError("route misses obstruction interval")
    if not scene.sidewalk.contains(*scene.route[0]) or not scene.sidewalk.contains(*scene.route[-1]):
        raise ValueError("route does not start and return on sidewalk")
    return {"case_id": scene.case_id, "sample_count": len(samples),
            "designated_lane_used": in_lane, "obstacle_count": len(scene.obstacles),
            "missing_surface_count": len(scene.missing_sections),
            "obstruction_kind": scene.obstruction_kind,
            "engineering_route_clear": True, "legal_judgment": "unresolved"}

"""Seal synchronized Native pedestrian observations for saved-only measurement.

The caller supplies readbacks from the same world snapshot as each walking
sample. This writer never labels a fixture as original acquisition.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from saved_measurement import REQUIRED
from native_walking import run_constructed
from native_construction import load_site_survey

STREAMS = ("video_frames.jsonl", "pedestrian_history.jsonl",
           "obstruction_history.jsonl", "traffic_history.jsonl")


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _valid_digest(value: object) -> bool:
    return isinstance(value, str) and len(value) == 64 and all(c in "0123456789abcdef" for c in value)


class NativeSourcePacket:
    """Collect one measured world tick and its four source observations at a time."""

    def __init__(self, case_id: str, survey_path: Path, survey_sha256: str,
                 camera_profile_sha256: str, traffic_plan_sha256: str,
                 pedestrian_blueprint: str):
        raw = Path(survey_path).read_bytes()
        if _sha(raw) != survey_sha256:
            raise ValueError("Native survey digest mismatch")
        load_site_survey(Path(survey_path), survey_sha256)
        if not case_id.startswith("testing__C104081__NRS-484B-297-6__pedestrian__"):
            raise ValueError("wrong exact pedestrian case")
        if not _valid_digest(camera_profile_sha256) or not _valid_digest(traffic_plan_sha256):
            raise ValueError("source-bound camera and traffic plan digests required")
        if not isinstance(pedestrian_blueprint, str) or not pedestrian_blueprint.startswith("walker.pedestrian."):
            raise ValueError("original pedestrian blueprint identity required")
        self.case_id = case_id
        self.survey = raw
        self.context = {"pedestrian_blueprint": pedestrian_blueprint,
                        "camera_profile_sha256": camera_profile_sha256,
                        "traffic_plan_sha256": traffic_plan_sha256}
        self.rows = {name: [] for name in STREAMS}

    def observe(self, walking_sample: dict, readbacks: dict) -> None:
        """Reject stale or unsynchronized source packets before retaining them."""
        frame, time_s = walking_sample.get("frame"), walking_sample.get("time_s")
        if type(frame) is not int or type(time_s) not in (int, float) or not math.isfinite(time_s):
            raise ValueError("invalid measured Native frame/time")
        index = len(self.rows[STREAMS[0]])
        if index:
            previous = self.rows[STREAMS[0]][-1]
            if frame != previous["carla_frame"] + 1 or abs(time_s - previous["time_s"] - .05) > .001:
                raise ValueError("Native capture 20 Hz frame continuity failure")
        if set(readbacks) != set(STREAMS):
            raise ValueError("all four synchronized Native source readbacks required")
        expected = {"carla_frame": frame, "video_frame": index, "time_s": time_s}
        frozen = {}
        for name in STREAMS:
            row = readbacks[name]
            if not isinstance(row, dict):
                raise ValueError("Native source row must be an object")
            if name == "video_frames.jsonl":
                if row != expected:
                    raise ValueError("Native video map does not join measured frame/time")
            elif row.get("frame") != frame or type(row.get("time_s")) not in (int, float) or abs(row["time_s"] - time_s) > 1e-4:
                raise ValueError("Native source does not join measured frame/time")
            # Freeze each readback now: later adapter mutations cannot change a sealed row.
            frozen[name] = json.loads(json.dumps(row, allow_nan=False))
        for name in STREAMS:
            self.rows[name].append(frozen[name])

    def seal(self, output: Path) -> dict:
        """Write the original-source packet after exactly 900 contiguous ticks."""
        if any(len(rows) != 900 for rows in self.rows.values()):
            raise ValueError("900 synchronized Native frames required")
        output = Path(output)
        if output.exists() and any(output.iterdir()):
            raise ValueError("Native packet output must be empty")
        output.mkdir(parents=True, exist_ok=True)
        payloads = {"site-survey.json": self.survey}
        for name, rows in self.rows.items():
            payloads[name] = ("".join(json.dumps(row, sort_keys=True, allow_nan=False) + "\n"
                                      for row in rows)).encode()
        if set(payloads) != set(REQUIRED):
            raise ValueError("saved measurement source contract changed")
        for name, raw in payloads.items():
            (output / name).write_bytes(raw)
        packet = {"case_id": self.case_id, "source_kind": "original_saved_acquisition",
                  "capture_context": self.context,
                  "files": {name: {"path": name, "sha256": _sha(payloads[name])}
                            for name in REQUIRED}}
        (output / "source-packet.json").write_text(json.dumps(packet, indent=2) + "\n")
        return packet


def capture_constructed_sources(world, walker, carla, constructed: dict,
                                survey_path: Path, case_id: str, source_reader,
                                output: Path, *, camera_profile_sha256: str,
                                traffic_plan_sha256: str, pedestrian_blueprint: str,
                                speed_m_s: float = 1.4, camera_recorder=None,
                                on_core_sample=None) -> dict:
    """Run the measured route and read all source streams at each Native tick.

    `source_reader(sample)` must read the just-ticked Native world, including
    original body, obstacle, traffic and video-frame identity. The caller owns
    world settings, actors and cameras. The writer retains no planned positions
    as observations and does not certify visibility or legal judgments.
    """
    packet = NativeSourcePacket(case_id, survey_path, constructed.get("survey_sha256"),
                                camera_profile_sha256, traffic_plan_sha256,
                                pedestrian_blueprint)

    def observe(sample):
        packet.observe(sample, source_reader(sample))
        if on_core_sample is not None:
            on_core_sample(sample["frame"], sample["time_s"])

    try:
        run_constructed(world, walker, carla, constructed, survey_path, case_id,
                        speed_m_s=speed_m_s, on_sample=observe)
        result = packet.seal(output)
        if camera_recorder is not None:
            result["camera_media"] = camera_recorder.seal(output)
        original_packet = output / "source-packet.json"
        (output / "pedestrian-packet.json").write_bytes(original_packet.read_bytes())
        return result
    except Exception:
        if camera_recorder is not None:
            camera_recorder.abort()
        raise

"""Stream original synchronized CARLA BGRA images into four lossless videos.

The caller owns the camera actors and a synchronizer that returns their original
image objects. This adapter checks identity, dimensions and world-frame joins.
It never creates or substitutes an image for a missing sensor observation.
"""
from __future__ import annotations

import hashlib
import json
import subprocess
from pathlib import Path

from native_readback import CAMERAS

PROFILE = {"overview": (1920, 1080), "approach": (1280, 720),
           "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def _sha(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


class NativeCameraRecorder:
    """Encode four original camera images, one synchronized world tick at a time."""

    def __init__(self, output: Path, sensors: dict, *, dimensions=None,
                 expected_frames: int = 900):
        self.output = Path(output)
        if self.output.exists() and any(self.output.iterdir()):
            raise ValueError("original camera output must be empty")
        self.output.mkdir(parents=True, exist_ok=True)
        self.dimensions = dict(PROFILE if dimensions is None else dimensions)
        if set(sensors) != set(CAMERAS) or set(self.dimensions) != set(CAMERAS):
            raise ValueError("four exact original camera actors and dimensions required")
        ids = [getattr(sensors[name], "id", None) for name in CAMERAS]
        if any(type(value) is not int or value < 0 for value in ids) or len(set(ids)) != 4:
            raise ValueError("four distinct original camera sensor IDs required")
        if type(expected_frames) is not int or expected_frames < 1:
            raise ValueError("positive original frame count required")
        self.sensor_ids = dict(zip(CAMERAS, ids))
        self.expected_frames = expected_frames
        self.processes = {}
        self.count = 0
        self.first_frame = None
        self.closed = False

    def _start(self, name: str):
        width, height = self.dimensions[name]
        if type(width) is not int or type(height) is not int or width < 1 or height < 1:
            raise ValueError("invalid original camera dimensions")
        path = self.output / f"{name}.mkv"
        process = subprocess.Popen(
            ["ffmpeg", "-v", "error", "-xerror", "-y", "-f", "rawvideo",
             "-pixel_format", "bgra", "-video_size", f"{width}x{height}",
             "-framerate", "20", "-i", "pipe:0", "-an", "-c:v", "ffv1",
             "-level", "3", "-pix_fmt", "bgr0", str(path)],
            stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
        self.processes[name] = process

    def __call__(self, frame: int, images: dict) -> dict:
        """Consume original sensor images and return camera IDs for actor readback."""
        if self.closed or self.count >= self.expected_frames:
            raise ValueError("original camera capture is closed or complete")
        if type(frame) is not int or set(images) != set(CAMERAS):
            raise ValueError("four synchronized original camera images required")
        if self.first_frame is None:
            self.first_frame = frame
        if frame != self.first_frame + self.count:
            raise ValueError("original camera world frames are not contiguous")
        payloads = {}
        for name in CAMERAS:
            image = images[name]
            width, height = self.dimensions[name]
            if (type(getattr(image, "frame", None)) is not int or image.frame != frame or
                    getattr(image, "sensor_id", None) != self.sensor_ids[name] or
                    getattr(image, "width", None) != width or
                    getattr(image, "height", None) != height):
                raise ValueError(f"original camera identity, frame or dimensions mismatch: {name}")
            raw = getattr(image, "raw_data", None)
            if not isinstance(raw, (bytes, bytearray, memoryview)) or len(raw) != width * height * 4:
                raise ValueError(f"original BGRA pixel payload missing or incomplete: {name}")
            payloads[name] = raw
        for name in CAMERAS:
            if name not in self.processes:
                self._start(name)
            process = self.processes[name]
            if process.poll() is not None:
                raise ValueError(f"original camera encoder exited early: {name}")
            try:
                process.stdin.write(payloads[name])
            except (BrokenPipeError, OSError) as exc:
                raise ValueError(f"original camera encoder write failed: {name}") from exc
        self.count += 1
        return {name: frame for name in CAMERAS}

    def seal(self, packet_dir: Path) -> dict:
        """Close encoders and bind their hashes to the saved source packet."""
        if self.closed or self.count != self.expected_frames or set(self.processes) != set(CAMERAS):
            raise ValueError("complete original four-camera capture required")
        self.closed = True
        for name in CAMERAS:
            process = self.processes[name]
            process.stdin.close()
            error = process.stderr.read().decode("utf-8", "replace")
            process.stderr.close()
            if process.wait() != 0:
                raise ValueError(f"original camera encode failed: {name}: {error[:200]}")
        packet_dir = Path(packet_dir)
        packet_path = packet_dir / "source-packet.json"
        packet = json.loads(packet_path.read_text())
        if packet.get("source_kind") != "original_saved_acquisition" or "camera_media" in packet:
            raise ValueError("unbound original source packet required")
        media = {}
        for name in CAMERAS:
            source = self.output / f"{name}.mkv"
            target = packet_dir / source.name
            if target.exists() or not source.is_file() or source.stat().st_size == 0:
                raise ValueError("camera media target collision or empty encode")
            source.replace(target)
            media[name] = {"path": target.name, "sha256": _sha(target),
                           "frame_count": self.count, "fps": 20,
                           "sensor_id": self.sensor_ids[name]}
        packet["camera_media"] = media
        packet_path.write_text(json.dumps(packet, indent=2) + "\n")
        return media

    def abort(self) -> None:
        """Release encoders after an incomplete or rejected capture."""
        if self.closed:
            return
        self.closed = True
        for process in self.processes.values():
            if process.stdin and not process.stdin.closed:
                process.stdin.close()
            if process.poll() is None:
                process.terminate()
            process.wait()
            if process.stderr and not process.stderr.closed:
                process.stderr.close()

"""Own four surveyed CARLA RGB camera actors and synchronize original images.

Camera poses must come from the hashed original site survey. This module is
CARLA lazy: CPU fakes exercise ownership and frame joins without a simulator.
"""
from __future__ import annotations

import math
from queue import Empty, Queue
from types import SimpleNamespace

from native_camera_capture import CAMERAS, NativeCameraRecorder, PROFILE
from native_construction import load_site_survey


class NativeCameraRig:
    def __init__(self, world, carla, survey_path, survey_sha256, output, *,
                 dimensions=None, timeout_s=3.0):
        survey = load_site_survey(survey_path, survey_sha256)
        views = survey.get("camera_views")
        if not isinstance(views, dict) or set(views) != set(CAMERAS):
            raise ValueError("four original surveyed camera views required")
        if not isinstance(timeout_s, (int, float)) or not math.isfinite(timeout_s) or timeout_s <= 0:
            raise ValueError("positive camera callback timeout required")
        self.dimensions = dict(PROFILE if dimensions is None else dimensions)
        if set(self.dimensions) != set(CAMERAS):
            raise ValueError("four exact camera dimensions required")
        self.timeout_s = timeout_s
        self.sensors = {}
        self.queues = {name: Queue(maxsize=4) for name in CAMERAS}
        self.closed = False
        self.recorder = None
        transform = survey["local_to_world"]
        yaw = math.radians(transform["yaw_degrees"])
        try:
            library = world.get_blueprint_library()
            for name in CAMERAS:
                view = views[name]
                if not isinstance(view, dict) or set(view) != {"x", "y", "z", "yaw", "pitch", "roll"}:
                    raise ValueError(f"surveyed camera pose incomplete: {name}")
                if not all(type(value) in (int, float) and math.isfinite(value)
                           for value in view.values()):
                    raise ValueError(f"surveyed camera pose nonfinite: {name}")
                width, height = self.dimensions[name]
                if type(width) is not int or type(height) is not int or width < 1 or height < 1:
                    raise ValueError("invalid original camera dimensions")
                blueprint = library.find("sensor.camera.rgb")
                blueprint.set_attribute("image_size_x", str(width))
                blueprint.set_attribute("image_size_y", str(height))
                blueprint.set_attribute("fov", "90")
                blueprint.set_attribute("sensor_tick", "0.05")
                x = transform["x"] + view["x"] * math.cos(yaw) - view["y"] * math.sin(yaw)
                y = transform["y"] + view["x"] * math.sin(yaw) + view["y"] * math.cos(yaw)
                pose = carla.Transform(
                    carla.Location(x=x, y=y, z=view["z"]),
                    carla.Rotation(yaw=transform["yaw_degrees"] + view["yaw"],
                                   pitch=view["pitch"], roll=view["roll"]))
                sensor = world.spawn_actor(blueprint, pose)
                self.sensors[name] = sensor
                queue = self.queues[name]
                queue_sensor_id = sensor.id

                def on_image(image, *, target=queue, sensor_id=queue_sensor_id):
                    if target.full():
                        return
                    target.put_nowait((sensor_id, image))

                sensor.listen(on_image)
            self.recorder = NativeCameraRecorder(output, self.sensors,
                                                 dimensions=self.dimensions)
        except BaseException:
            self.close()
            raise

    def sync(self, frame: int) -> dict:
        """Read one image from each actor at exactly this world frame."""
        if self.closed or type(frame) is not int:
            raise ValueError("original camera rig closed or invalid frame")
        images = {}
        for name in CAMERAS:
            try:
                sensor_id, image = self.queues[name].get(timeout=self.timeout_s)
            except Empty as exc:
                raise ValueError(f"missing original camera callback: {name}") from exc
            if sensor_id != self.sensors[name].id or getattr(image, "frame", None) != frame:
                raise ValueError(f"stale or mismatched original camera callback: {name}")
            images[name] = SimpleNamespace(frame=image.frame, sensor_id=sensor_id,
                                           width=image.width, height=image.height,
                                           raw_data=image.raw_data)
        return self.recorder(frame, images)

    def close(self) -> None:
        if self.closed:
            return
        self.closed = True
        if self.recorder is not None:
            self.recorder.abort()
        errors = []
        for name in reversed(tuple(self.sensors)):
            sensor = self.sensors[name]
            try:
                sensor.stop()
                sensor.destroy()
            except BaseException as exc:
                errors.append(f"{name}: {exc}")
        if errors:
            raise RuntimeError("camera actor cleanup failed: " + "; ".join(errors))

"""Source-bound saved pedestrian bypass measurements for NRS 484B.297(6).

Reads original-shaped frame, body, obstruction and traffic histories. A fixture
may exercise the same computation, but is labelled diagnostic and never accepted
as physical or legal evidence. No CARLA connection is made here.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

REQUIRED = ("site-survey.json", "video_frames.jsonl", "pedestrian_history.jsonl",
            "obstruction_history.jsonl", "traffic_history.jsonl")


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _finite(value):
    return type(value) in (int, float) and math.isfinite(value)


def _rows(path: Path) -> list[dict]:
    rows = [json.loads(line) for line in path.read_text().splitlines() if line.strip()]
    if not rows:
        raise ValueError(f"empty saved source: {path.name}")
    return rows


def _point(value, name: str) -> tuple[float, float]:
    if not isinstance(value, list) or len(value) < 2 or not all(_finite(v) for v in value[:2]):
        raise ValueError(f"missing finite {name}")
    return float(value[0]), float(value[1])


def _local(point, transform):
    x, y = _point(point, "world point")
    angle = math.radians(transform["yaw_degrees"])
    dx, dy = x - transform["x"], y - transform["y"]
    return (dx * math.cos(angle) + dy * math.sin(angle),
            -dx * math.sin(angle) + dy * math.cos(angle))


def _inside(point, bounds):
    x, y = point
    return bounds[0] <= x <= bounds[1] and bounds[2] <= y <= bounds[3]


def _polygon_bounds(vertices, transform, name):
    if not isinstance(vertices, list) or len(vertices) < 4:
        raise ValueError(f"missing observed {name} geometry")
    points = [_local(vertex, transform) for vertex in vertices]
    return [min(p[0] for p in points), max(p[0] for p in points),
            min(p[1] for p in points), max(p[1] for p in points)]


def _within_bounds(box, surface, tolerance=1e-6):
    return (box[0] >= surface[0] - tolerance and box[1] <= surface[1] + tolerance and
            box[2] >= surface[2] - tolerance and box[3] <= surface[3] + tolerance)


def _bounds(survey, name):
    value = survey.get("surface_bounds_local_m", {}).get(name)
    if not isinstance(value, list) or len(value) != 4 or not all(_finite(x) for x in value):
        raise ValueError(f"missing surveyed bounds: {name}")
    if value[0] >= value[1] or value[2] >= value[3]:
        raise ValueError(f"invalid surveyed bounds: {name}")
    return value


def measure_saved(root: Path, expected_case_id: str) -> dict:
    """Compute observable histories from digest-bound saved acquisition only."""
    root = Path(root)
    packet_path = root / "source-packet.json"
    packet = json.loads(packet_path.read_text())
    if packet.get("case_id") != expected_case_id:
        raise ValueError("saved source exact case mismatch")
    kind = packet.get("source_kind")
    if kind not in ("original_saved_acquisition", "synthetic_fixture"):
        raise ValueError("unknown saved acquisition provenance")
    bindings = packet.get("files")
    if not isinstance(bindings, dict) or set(bindings) != set(REQUIRED):
        raise ValueError("missing exact saved source binding")
    hashes = {}
    for name in REQUIRED:
        binding = bindings[name]
        if not isinstance(binding, dict) or binding.get("path") != name:
            raise ValueError(f"nonlocal or mismatched source binding: {name}")
        path = root / name
        if not path.is_file():
            raise ValueError(f"missing required saved source: {name}")
        digest = _sha(path)
        if digest != binding.get("sha256"):
            raise ValueError(f"saved source digest mismatch: {name}")
        hashes[name] = digest
    survey = json.loads((root / "site-survey.json").read_text())
    if survey.get("cell_id") != "C104081" or survey.get("layout") != "hill_crest":
        raise ValueError("saved survey cell/layout mismatch")
    if kind == "original_saved_acquisition":
        if survey.get("source_kind") != "original_native_map_survey":
            raise ValueError("original saved acquisition lacks original Native survey")
        for name in ("sidewalk", "intervening_area", "designated_bicycle_lane", "immediately_adjacent_highway"):
            if survey.get("surfaces", {}).get(name, {}).get("surveyed") is not True:
                raise ValueError("original Native survey lacks observed surface: " + name)
    transform = survey.get("local_to_world", {})
    if not all(_finite(transform.get(k)) for k in ("x", "y", "yaw_degrees")):
        raise ValueError("survey lacks finite local-to-world transform")
    sidewalk = _bounds(survey, "sidewalk")
    area = _bounds(survey, "intervening_area")
    lane = _bounds(survey, "designated_bicycle_lane")
    highway = _bounds(survey, "immediately_adjacent_highway")
    if area[3] != sidewalk[2] or lane[3] != area[2] or highway[3] != sidewalk[2]:
        raise ValueError("surveyed surfaces are not contiguous")
    mapping = _rows(root / "video_frames.jsonl")
    pedestrian = _rows(root / "pedestrian_history.jsonl")
    obstructions = _rows(root / "obstruction_history.jsonl")
    traffic = _rows(root / "traffic_history.jsonl")
    if not (len(mapping) == len(pedestrian) == len(obstructions) == len(traffic)) or len(mapping) < 3:
        raise ValueError("saved history lengths or sample count mismatch")
    previous_frame = -1
    previous_time = -1.0
    centers = []
    lane_frames = []
    highway_frames = []
    sidewalk_frames = []
    obstruction_ends = set()
    obstruction_kinds = set()
    barrier_states = set()
    traffic_context = []
    obstruction_geometry = set()
    barrier_geometry = set()
    for index, (frame_map, walker, obstacle, vehicle) in enumerate(zip(mapping, pedestrian, obstructions, traffic)):
        frame = frame_map.get("carla_frame")
        time = frame_map.get("time_s")
        if type(frame) is not int or frame <= previous_frame or not _finite(time) or time <= previous_time:
            raise ValueError("original frame identity is nonmonotonic")
        if index and abs((time - previous_time) - 0.05) > 1e-3:
            raise ValueError("saved acquisition is not at pinned 20 Hz")
        if frame_map.get("video_frame") != index:
            raise ValueError("original video frame index mismatch")
        for row in (walker, obstacle, vehicle):
            if row.get("frame") != frame or not _finite(row.get("time_s")) or abs(row["time_s"] - time) > 1e-4:
                raise ValueError("saved histories do not join original frame/time")
        vertices = walker.get("body_vertices_world_m")
        if not isinstance(vertices, list) or len(vertices) < 4:
            raise ValueError("missing complete walker body vertices")
        points = [_local(vertex, transform) for vertex in vertices]
        center = ((min(p[0] for p in points) + max(p[0] for p in points)) / 2,
                  (min(p[1] for p in points) + max(p[1] for p in points)) / 2)
        if not _inside(center, sidewalk) and not _inside(center, highway):
            raise ValueError("pedestrian center leaves surveyed sidewalk/highway")
        centers.append(center)
        if _inside(center, lane): lane_frames.append(frame)
        if _inside(center, highway) and not _inside(center, sidewalk): highway_frames.append(frame)
        if _inside(center, sidewalk): sidewalk_frames.append(frame)
        if type(obstacle.get("intervening_barrier_present")) is not bool:
            raise ValueError("missing observed intervening barrier state")
        barrier_states.add(obstacle["intervening_barrier_present"])
        obstruction_box = _polygon_bounds(obstacle.get("sidewalk_obstruction_vertices_world_m"),
                                          transform, "sidewalk obstruction")
        if not _within_bounds(obstruction_box, sidewalk):
            raise ValueError("observed sidewalk obstruction leaves surveyed sidewalk")
        obstruction_geometry.add(tuple(round(v, 3) for v in obstruction_box))
        if obstacle["intervening_barrier_present"]:
            barrier_box = _polygon_bounds(obstacle.get("intervening_barrier_vertices_world_m"),
                                          transform, "intervening barrier")
            if not _within_bounds(barrier_box, area):
                raise ValueError("observed barrier leaves surveyed intervening area")
            barrier_geometry.add(tuple(round(v, 3) for v in barrier_box))
        elif obstacle.get("intervening_barrier_vertices_world_m"):
            raise ValueError("unreported observed intervening barrier geometry")
        end = obstacle.get("sidewalk_obstruction_end_local_m")
        if not _finite(end): raise ValueError("missing observed sidewalk obstruction extent")
        obstruction_ends.add(float(end))
        obstruction_kinds.add(obstacle.get("sidewalk_obstruction_kind"))
        if not _finite(vehicle.get("nearest_traffic_distance_m")) or vehicle["nearest_traffic_distance_m"] < 0:
            raise ValueError("missing finite traffic context")
        traffic_context.append(float(vehicle["nearest_traffic_distance_m"]))
        previous_frame, previous_time = frame, time
    if (len(barrier_states) != 1 or len(obstruction_ends) != 1 or
            len(obstruction_kinds) != 1 or len(obstruction_geometry) != 1 or
            len(barrier_geometry) > 1):
        raise ValueError("observed obstruction state changed during comparison")
    if obstruction_kinds.pop() not in ("impassable_section", "missing_section"):
        raise ValueError("unknown observed obstruction kind")
    kind_value = obstacle["sidewalk_obstruction_kind"]
    observed_end = next(iter(obstruction_ends))
    observed_box = next(iter(obstruction_geometry))
    if abs(observed_box[1] - observed_end) > 0.25:
        raise ValueError("observed sidewalk geometry disagrees with obstruction extent")
    if kind_value == "missing_section" and [round(observed_box[0], 3), round(observed_box[1], 3)] not in survey.get("observed_missing_sidewalk_intervals_local_m", []):
        raise ValueError("missing sidewalk section absent from source survey")
    if not sidewalk_frames or not highway_frames:
        raise ValueError("source lacks sidewalk-to-highway bypass")
    first_highway = highway_frames[0]
    last_highway = highway_frames[-1]
    if not any(f < first_highway for f in sidewalk_frames) or not any(f > last_highway for f in sidewalk_frames):
        raise ValueError("source lacks sidewalk origin or return")
    dx = centers[-1][0] - centers[0][0]
    if abs(dx) < 0.1: raise ValueError("saved route has no longitudinal travel")
    direction = 1 if dx > 0 else -1
    if direction != survey.get("original_sidewalk_direction"):
        raise ValueError("saved travel direction differs from original sidewalk direction")
    first_return = min(f for f in sidewalk_frames if f > last_highway)
    center_by_frame = {r["frame"]: p for r, p in zip(pedestrian, centers)}
    return {
        "format": "worker-saved-pedestrian-bypass-measurement", "case_id": expected_case_id,
        "provenance_kind": kind, "diagnostic_fixture": kind == "synthetic_fixture",
        "source_sha256": hashes, "source_packet_sha256": _sha(packet_path),
        "sample_count": len(mapping), "first_frame": mapping[0]["carla_frame"],
        "last_frame": mapping[-1]["carla_frame"], "observables": {
            "pedestrian_direction": direction, "designated_lane_used": bool(lane_frames),
            "designated_lane_frames": lane_frames, "highway_frames": highway_frames,
            "intervening_barrier_present": barrier_states.pop(),
            "sidewalk_obstruction_end_m": observed_end,
            "sidewalk_obstruction_bounds_local_m": list(observed_box),
            "intervening_barrier_bounds_local_m": list(next(iter(barrier_geometry))) if barrier_geometry else None,
            "sidewalk_obstruction_kind": kind_value,
            "first_sidewalk_return_frame": first_return,
            "return_center_local_m": list(center_by_frame[first_return]),
            "lateral_distance_to_sidewalk_edge_m": [sidewalk[2] - center_by_frame[f][1] for f in highway_frames],
            "nearest_traffic_distance_m": traffic_context,
        },
        "legal_judgment": "unresolved", "physical_acceptance": "not_assessed",
    }


def comparison_projection(root: Path, expected_case_id: str) -> dict:
    """Derive comparison fields from the measured saved histories and survey.

    The downstream comparison audit still rejects synthetic fixture provenance.
    A local operator must independently verify Native ownership of the sources.
    """
    root = Path(root)
    receipt = measure_saved(root, expected_case_id)
    packet = json.loads((root / "source-packet.json").read_text())
    survey = json.loads((root / "site-survey.json").read_text())
    context = packet.get("capture_context", {})
    if not isinstance(context, dict) or not isinstance(context.get("pedestrian_blueprint"), str) or not context["pedestrian_blueprint"]:
        raise ValueError("missing saved pedestrian blueprint")
    traffic_plan_hash = context.get("traffic_plan_sha256")
    if not isinstance(traffic_plan_hash, str) or len(traffic_plan_hash) != 64 or any(c not in "0123456789abcdef" for c in traffic_plan_hash):
        raise ValueError("missing bound traffic plan hash")
    camera_hash = context.get("camera_profile_sha256")
    if not isinstance(camera_hash, str) or len(camera_hash) != 64 or any(c not in "0123456789abcdef" for c in camera_hash):
        raise ValueError("missing bound camera profile hash")
    values = receipt["observables"]
    return {
        "source_kind": receipt["provenance_kind"], "case_id": expected_case_id,
        "cell_id": survey["cell_id"], "actor": "pedestrian", "map_id": survey.get("map_id"),
        "pedestrian_blueprint": context["pedestrian_blueprint"],
        "traffic_plan_sha256": traffic_plan_hash,
        "camera_profile_sha256": camera_hash, "duration_frames": receipt["sample_count"],
        "intervening_barrier_present": values["intervening_barrier_present"],
        "designated_lane_used": values["designated_lane_used"],
        "pedestrian_direction": values["pedestrian_direction"],
        "sidewalk_obstruction_end_m": values["sidewalk_obstruction_end_m"],
        "sidewalk_obstruction_kind": values["sidewalk_obstruction_kind"],
        "measurement_sources_sha256": receipt["source_sha256"],
        "source_packet_sha256": receipt["source_packet_sha256"],
        "physical_acceptance": "not_assessed", "legal_judgment": "unresolved",
    }


def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", required=True)
    parser.add_argument("--case", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--comparison-packet", action="store_true")
    args = parser.parse_args()
    result = (comparison_projection(args.attempt, args.case) if args.comparison_packet
              else measure_saved(args.attempt, args.case))
    output = Path(args.output)
    if output.exists():
        raise ValueError("preserve prior saved analysis; use a fresh output path")
    output.write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
    print(json.dumps({"case_id": args.case, "diagnostic_fixture": result["source_kind"] == "synthetic_fixture" if args.comparison_packet else result["diagnostic_fixture"]}))


if __name__ == "__main__":
    main()

"""Independent saved-source audit for the exact pedestrian bypass cases.

This verifies acquisition identity, original frame continuity, measurements and
sealed camera bytes. It deliberately leaves pixel visibility and physical/legal
completion unresolved; a metadata or diagnostic fixture is not acceptance.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import subprocess
from pathlib import Path

from saved_measurement import measure_saved

ASSIGNMENT = "testing__C104081__NRS-484B-297-6__pedestrian"
CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
EXPECTED_FRAMES = 900
EXPECTED_DIMENSIONS = {
    "overview": (1920, 1080),
    "approach": (1280, 720),
    "reference_corner": (1280, 720),
    "driver_reference": (1280, 720),
}
CASE_EXPECTATIONS = {
    "clear_intervening": (1, False, False, 34.0, "impassable_section"),
    "blocked_intervening": (1, True, True, 34.0, "impassable_section"),
    "blocked_opposite": (-1, True, True, 34.0, "impassable_section"),
    "blocked_late_return": (1, True, True, 40.0, "impassable_section"),
    "missing_sidewalk": (1, False, False, 34.0, "missing_section"),
}


def _digest(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _local_file(root: Path, relative: str) -> Path:
    if not isinstance(relative, str) or not relative or Path(relative).is_absolute():
        raise ValueError("media path must be relative to saved attempt")
    root = root.resolve()
    path = (root / relative).resolve()
    if not path.is_relative_to(root):
        raise ValueError("media path escapes saved attempt")
    if not path.is_file():
        raise ValueError("missing sealed camera file")
    return path


def _decode_media(path: Path, camera: str, *, diagnostic: bool) -> dict:
    """Count and fully decode one sealed camera video with installed CPU tools."""
    probe = subprocess.run(
        ["ffprobe", "-v", "error", "-select_streams", "v:0", "-count_frames",
         "-show_entries", "stream=width,height,r_frame_rate,nb_read_frames",
         "-of", "json", str(path)], capture_output=True, text=True, check=False,
    )
    if probe.returncode:
        raise ValueError(f"camera probe failed: {camera}: {probe.stderr.strip()[:200]}")
    try:
        streams = json.loads(probe.stdout)["streams"]
        if len(streams) != 1:
            raise ValueError("multiple selected video streams")
        stream = streams[0]
        count = int(stream["nb_read_frames"])
        width, height = int(stream["width"]), int(stream["height"])
        rate = stream["r_frame_rate"]
    except (KeyError, IndexError, TypeError, ValueError) as exc:
        raise ValueError(f"camera probe lacks complete video metadata: {camera}") from exc
    if count != EXPECTED_FRAMES or rate != "20/1":
        raise ValueError(f"decoded camera frame count or cadence mismatch: {camera}")
    if (width, height) != EXPECTED_DIMENSIONS[camera] and not diagnostic:
        raise ValueError(f"camera dimensions differ from capture profile: {camera}")
    decoded = subprocess.run(
        ["ffmpeg", "-v", "error", "-xerror", "-i", str(path),
         "-map", "0:v:0", "-f", "null", "-"],
        capture_output=True, text=True, check=False,
    )
    if decoded.returncode:
        raise ValueError(f"full camera decode failed: {camera}: {decoded.stderr.strip()[:200]}")
    return {"frame_count": count, "fps": 20, "width": width, "height": height,
            "profile_dimensions": (width, height) == EXPECTED_DIMENSIONS[camera]}


def audit_saved(root: Path, case_id: str, *, diagnostic: bool = False,
                decode_media: bool = False) -> dict:
    """Validate original-shaped saved sources; fixtures require explicit opt-in."""
    if not case_id.startswith(ASSIGNMENT + "__") or case_id[len(ASSIGNMENT) + 2:] not in CASE_EXPECTATIONS:
        raise ValueError("unknown exact pedestrian case")
    root = Path(root)
    packet_path = root / "source-packet.json"
    packet = json.loads(packet_path.read_text())
    if packet.get("case_id") != case_id:
        raise ValueError("saved source exact case mismatch")
    if packet.get("source_kind") != "original_saved_acquisition" and not diagnostic:
        raise ValueError("delivery requires original saved acquisition")
    measured = measure_saved(root, case_id)
    values = measured["observables"]
    actual_case = (
        values["pedestrian_direction"], values["intervening_barrier_present"],
        values["designated_lane_used"], values["sidewalk_obstruction_end_m"],
        values["sidewalk_obstruction_kind"],
    )
    if actual_case != CASE_EXPECTATIONS[case_id[len(ASSIGNMENT) + 2:]]:
        raise ValueError("measured bypass does not match exact planned case")
    if measured["sample_count"] != EXPECTED_FRAMES:
        raise ValueError("saved attempt lacks complete 900-frame history")
    rows = [json.loads(line) for line in (root / "video_frames.jsonl").read_text().splitlines() if line.strip()]
    if rows[-1]["carla_frame"] - rows[0]["carla_frame"] != EXPECTED_FRAMES - 1:
        raise ValueError("saved attempt skips original CARLA frames")
    if rows[-1]["video_frame"] != EXPECTED_FRAMES - 1:
        raise ValueError("saved attempt lacks final video frame")
    media = packet.get("camera_media")
    if not isinstance(media, dict) or set(media) != set(CAMERAS):
        raise ValueError("missing exact four-camera media binding")
    sealed = {}
    decoded_media = {}
    used_paths = set()
    for camera in CAMERAS:
        binding = media[camera]
        if not isinstance(binding, dict):
            raise ValueError("invalid camera media binding")
        relative = binding.get("path")
        path = _local_file(root, relative)
        if path in used_paths:
            raise ValueError("camera bindings reuse a media file")
        used_paths.add(path)
        digest = _digest(path)
        if digest != binding.get("sha256"):
            raise ValueError("camera media digest mismatch")
        if path.stat().st_size <= 0:
            raise ValueError("empty camera media")
        if binding.get("frame_count") != EXPECTED_FRAMES or binding.get("fps") != 20:
            raise ValueError("camera frame count or cadence differs from capture plan")
        sealed[camera] = {"path": relative, "sha256": digest}
        if decode_media:
            decoded_media[camera] = _decode_media(path, camera, diagnostic=diagnostic)
    return {
        "format": "worker-pedestrian-bypass-saved-source-audit",
        "case_id": case_id,
        "source_kind": packet["source_kind"],
        "source_packet_sha256": _digest(packet_path),
        "source_integrity": "passed",
        "measured_observables": measured["observables"],
        "original_frame_count": EXPECTED_FRAMES,
        "sealed_camera_media": sealed,
        "decoded_camera_media": decoded_media,
        "checks": {
            "native_source": packet["source_kind"] == "original_saved_acquisition",
            "all_participants": False,
            "time_join": True,
            "full_video_decode": decode_media,
            "actual_pixels": False,
            "physical_completion": False,
        },
        "legal_judgment": "unresolved",
        "physical_acceptance": "not_assessed",
    }


def audit_delivery(root: Path, case_id: str, review_path: Path) -> dict:
    """Require independent original-pixel review and sealed physical completion."""
    from original_review import audit_original_review
    source = audit_saved(root, case_id, decode_media=True)
    reviewed = audit_original_review(root, case_id, source, review_path)
    source["checks"] = reviewed["checks"]
    source["independent_review"] = {
        "pixel_review_sha256": reviewed["pixel_review_sha256"],
        "participant_census": reviewed["participant_census"],
    }
    source["physical_acceptance"] = "source_reviewed_pending_canonical_acceptance"
    return source


def main() -> None:
    parser = argparse.ArgumentParser(description="Audit exact saved pedestrian bypass sources")
    parser.add_argument("--attempt", required=True, type=Path)
    parser.add_argument("--case", required=True)
    parser.add_argument("--decode-media", action="store_true")
    parser.add_argument("--diagnostic", action="store_true")
    parser.add_argument("--review", type=Path,
                        help="independent original-pixel review after Native owner release")
    args = parser.parse_args()
    if args.review:
        if args.diagnostic:
            raise ValueError("diagnostic fixture cannot enter original pixel review")
        receipt = audit_delivery(args.attempt, args.case, args.review)
    else:
        receipt = audit_saved(args.attempt, args.case, diagnostic=args.diagnostic,
                              decode_media=args.decode_media)
    print(json.dumps(receipt, sort_keys=True))


if __name__ == "__main__":
    main()

"""Independent source-bound comparison audit for prepared 297(6) cases.

This accepts only source packets labeled as original saved acquisition. Unit
tests use synthetic packets solely to exercise rejection branches. It makes no
legal or physical acceptance decision about impassability or due care.
"""

import hashlib
import json
from pathlib import Path


FIXED_KEYS = ("cell_id", "actor", "map_id", "pedestrian_blueprint",
              "traffic_plan_sha256", "camera_profile_sha256", "duration_frames")
VARIABLE_KEYS = ("intervening_barrier_present", "designated_lane_used",
                 "pedestrian_direction", "sidewalk_obstruction_end_m",
                 "sidewalk_obstruction_kind")
ALLOWED_DIFFS = {
    "intervening_area_condition": {"intervening_barrier_present", "designated_lane_used"},
    "travel_direction": {"pedestrian_direction"},
    "sidewalk_return_opportunity": {"sidewalk_obstruction_end_m"},
    "sidewalk_obstruction_type": {"sidewalk_obstruction_kind"},
}


def read_packet(path: Path, expected_sha256: str) -> dict:
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError(f"source digest mismatch: {path}")
    packet = json.loads(raw)
    if packet.get("source_kind") != "original_saved_acquisition":
        raise ValueError("comparison requires original saved acquisition")
    for key in ("case_id", *FIXED_KEYS, *VARIABLE_KEYS):
        if packet.get(key) is None:
            raise ValueError(f"missing measured field: {key}")
    if packet["duration_frames"] <= 0:
        raise ValueError("empty measured frame history")
    if packet["pedestrian_direction"] not in (-1, 1):
        raise ValueError("invalid pedestrian direction")
    if not isinstance(packet["intervening_barrier_present"], bool):
        raise ValueError("barrier observation must be boolean")
    if not isinstance(packet["designated_lane_used"], bool):
        raise ValueError("lane-use observation must be boolean")
    return packet


def audit(plan: dict, sources: dict[str, dict]) -> dict:
    """Return comparison facts or reject missing/changed original evidence."""
    cases = {c["case_id"]: c for c in plan["cases"]}
    if set(sources) != set(cases):
        raise ValueError("source packets do not cover exact planned cases")
    packets = {}
    for case_id, binding in sources.items():
        packet = read_packet(Path(binding["path"]), binding["sha256"])
        if packet["case_id"] != case_id:
            raise ValueError("source packet case mismatch")
        packets[case_id] = packet
    return _audit_packets(plan, packets, sources)


def _audit_packets(plan: dict, packets: dict, sources: dict) -> dict:
    findings = []
    for comparison in plan["comparisons"]:
        comparison_id = comparison["comparison_id"]
        if comparison_id not in ALLOWED_DIFFS or len(comparison["case_ids"]) != 2:
            raise ValueError("unknown or malformed comparison")
        first, second = (packets[x] for x in comparison["case_ids"])
        for key in FIXED_KEYS:
            if first[key] != second[key]:
                raise ValueError(f"fixed condition changed: {comparison_id}: {key}")
        actual = {key for key in VARIABLE_KEYS if first[key] != second[key]}
        if actual != ALLOWED_DIFFS[comparison_id]:
            raise ValueError(f"comparison changed wrong variables: {comparison_id}: {sorted(actual)}")
        findings.append({"comparison_id": comparison_id, "case_ids": comparison["case_ids"],
                         "observed_differences": sorted(actual), "fixed_conditions_verified": list(FIXED_KEYS),
                         "source_sha256": [sources[x]["sha256"] for x in comparison["case_ids"]]})
    return {"status": "source_consistency_passed", "findings": findings,
            "legal_judgment": "unresolved", "physical_acceptance": "not_assessed"}


def audit_saved_attempts(plan: dict, attempt_roots: dict[str, str]) -> dict:
    """Run the independent comparison from exact sealed saved attempts.

    This branch accepts only original-shaped acquisition. Diagnostic fixture
    packets remain useful for unit tests but cannot enter an accepted comparison.
    """
    from saved_measurement import comparison_projection

    cases = {case["case_id"] for case in plan["cases"]}
    if set(attempt_roots) != cases:
        raise ValueError("saved attempts do not cover exact planned cases")
    packets = {}
    sources = {}
    for case_id, root in attempt_roots.items():
        packet = comparison_projection(Path(root), case_id)
        if packet["source_kind"] != "original_saved_acquisition":
            raise ValueError("comparison requires original saved acquisition")
        packets[case_id] = packet
        sources[case_id] = {"sha256": packet["source_packet_sha256"]}
    return _audit_packets(plan, packets, sources)

